// The exercise library: steps and pictures for the built-in exercises, plus
// ~700 more to search. Generated by scripts/build-exercise-library.mjs from
// Free Exercise DB (public domain), pinned to one commit.
import data from '../data/exercise-library.json' with { type: 'json' };
import type { Muscle } from '@forkbell/shared';

export interface HowTo {
  /** the Free Exercise DB id, which is also its picture folder */
  ref: string;
  level: string | null;
  secondary: string[];
  steps: string[];
  /** how many pictures (usually 2: the start and the end of the movement) */
  images: number;
}

export interface LibraryExercise extends HowTo {
  key: string;
  name: string;
  muscle: Muscle;
  equipment: string;
  kind: 'weight' | 'bodyweight' | 'time';
  increment: 'small' | 'large';
  restSeconds: number;
}

export const exerciseLibrary = data as unknown as {
  source: string;
  commit: string;
  core: Record<string, HowTo>;
  library: LibraryExercise[];
};

/** Picture folders that exist, with how many pictures each has. Nothing else can be fetched. */
export const howToImages: ReadonlyMap<string, number> = new Map([
  ...Object.values(exerciseLibrary.core).map((h) => [h.ref, h.images] as const),
  ...exerciseLibrary.library.map((h) => [h.ref, h.images] as const),
]);
